from lib import *
S = SS('w34')
steps = [
    step("IGMP 报文格式(手工构造,不是抓来的;地址是文档地址):v2 通用查询的 IGMP 部分 8 字节,v3 通用查询 12 字节,v3 组-源查询(2 个源)20 字节,v2 成员报告 8 字节,v3 报告(1 条记录,EXCLUDE 空 = 加入整个组)16 字节,v3 报告(2 条记录:INCLUDE{S1,S2} 和 EXCLUDE{})32 字节;每个报文的校验和都验算通过,加上 24 字节的 IP 头(含 Router Alert)后整个 IP 包是 32、36、44、32、40、56 字节。区分 v1 / v2 / v3 查询靠 IGMP 部分的长度:长度 8 且最大响应时间为 0 是 v1,长度 8 且不为 0 是 v2,长度 ≥ 12 是 v3。v3 的 8 位最大响应码 ≥ 128 时用浮点格式:2000 个 0.1 秒编码成 0xc0,解回来是 2048(只能表示近似值)。v3 报告发往 224.0.0.22,v2 报告发往被报告的组地址本身,v2 离开发往 224.0.0.2。", t=tl(S(1)), mark=lidx(S(1), 'v3 通用查询', 'v3 组-源查询', 'v3 报告(1 条记录', 'v3 报告(2 条记录'), done=lidx(S(1), 'v2 通用查询', 'v2 成员报告', 'v1 / v2 / v3 查询的区分', 'v3 报告发往'), b=bars([['v2 查询 / 报告', 8, '8 字节'], ['v3 通用查询', 12, '12 字节'], ['v3 组-源查询(2 个源)', 20, '20 字节'], ['v3 报告(1 条记录)', 16, '16 字节'], ['v3 报告(2 条记录,含 2 个源)', 32, '32 字节']], 32, mark=[3, 4], done=[0, 1, 2]), kv=KV([['v2', '8 字节,单组'], ['v3 查询', '≥ 12 字节,可带源列表'], ['v3 报告', '8 字节头 + 每条记录 8 字节起 + 4 字节/源'], ['发往', 'v3 报告 → 224.0.0.22;v2 报告 → 组地址']], ['v3 报告'])),
    step("解码验证:把上面 6 个报文写成 pcap,tcpdump -vv 解出 igmp query v2、igmp query v3、igmp query v3 [gaddr 239.255.42.99 { 198.51.100.7 198.51.100.8 }]、igmp v2 report 239.255.42.99、igmp v3 report, 1 group record(s) [gaddr 239.255.42.99 is_ex { }]、igmp v3 report, 2 group record(s) [… is_in { 198.51.100.7 198.51.100.8 }] [… is_ex { }],IP 头都是 (tos 0xc0, ttl 1, options (RA))。scapy 把这 6 个包解成 IGMP_MQ / IGMPv3_MQ / IGMPv3_MQ / IGMPv2_MR / IGMPv3_MR / IGMPv3_MR;最后一个 v3 报告解出记录数 2、记录类型 [1, 2](MODE_IS_INCLUDE、MODE_IS_EXCLUDE)、两个组、源 [198.51.100.7, 198.51.100.8] 和 [],与我构造的完全一致。", t=tl(S(2)), mark=lidx(S(2), 'igmp query v3 [gaddr', 'igmp v3 report, 1 group', 'igmp v3 report, 2 group', 'scapy 解出最后'), done=lidx(S(2), 'igmp query v2', 'igmp v2 report', 'scapy 对这 6 个'), kv=KV([['tcpdump', '6 个报文都解出,含源列表'], ['scapy', 'MQ / MR 类型和记录与构造一致'], ['IP 头', 'tos 0xc0, ttl 1, options (RA)']], ['scapy'])),
    step("v3 报告的记录类型:当前状态报告(MODE_IS_INCLUDE = 1、MODE_IS_EXCLUDE = 2)和状态变化报告(CHANGE_TO_INCLUDE = 3、CHANGE_TO_EXCLUDE = 4、ALLOW_NEW_SOURCES = 5、BLOCK_OLD_SOURCES = 6)。套接字操作对应(这一节是对应关系的整理,不是抓到的):IP_ADD_MEMBERSHIP(任意源加入)→ CHANGE_TO_EXCLUDE{}(接收任何源);IP_DROP_MEMBERSHIP(离开)→ CHANGE_TO_INCLUDE{}(不接收任何源 = 离开,v2 里是专门的 Leave 报文);IP_ADD_SOURCE_MEMBERSHIP(只要某个源)→ CHANGE_TO_INCLUDE{S};再加一个源 → ALLOW_NEW_SOURCES{S2};IP_BLOCK_SOURCE → BLOCK_OLD_SOURCES{S} 或 CHANGE_TO_EXCLUDE{S}。本机没有发过 v3 报文,所以这些映射没有在线上验证。", t=tl(S(3)), mark=lidx(S(3), 'IP_ADD_MEMBERSHIP', 'IP_ADD_SOURCE_MEMBERSHIP'), done=lidx(S(3), 'IP_DROP_MEMBERSHIP', '再加一个源', 'IP_BLOCK_SOURCE'), kv=KV([['任意源加入', 'CHANGE_TO_EXCLUDE{}'], ['只要某个源', 'CHANGE_TO_INCLUDE{S}'], ['再加源', 'ALLOW_NEW_SOURCES'], ['屏蔽源', 'BLOCK_OLD_SOURCES / CHANGE_TO_EXCLUDE'], ['验证', '本机只发 v2,未在线上验证']], ['验证'])),
    step("套接字的源过滤和线上实际发的 IGMP:每种过滤方式用独立的套接字、独立的端口依次测试;发送方的源地址就是本机 en0 的地址。不过滤(任意源)→ 收到;只要本机地址这个源 → 收到;只要另一个源(198.51.100.7)→ 没收到——内核确实按源地址过滤了;但是“任意源加入后屏蔽本机地址这个源”仍然收到了,屏蔽另一个源也收到(后者符合预期)。前者没被屏蔽的原因没有查,可能与本机自己回送的组播副本不走同样的过滤有关,这只是猜测。线上方面,这五组加入 / 屏蔽 / 离开的过程共发出 16 个 IGMP 报文,全是 v2:0x16(v2 报告)11 个、0x17(v2 离开)5 个——这个网段上的查询者是 v2,本机按 v2 说话,v2 里没有“源”的概念,过滤信息只存在于本机内核里,没有告诉路由器。", t=tl(S(4)), mark=lidx(S(4), '任意源加入后屏蔽本机地址这个源', '只要另一个源', '这些加入 / 屏蔽 / 离开'), done=lidx(S(4), '不过滤(任意源)', '只要本机地址这个源', '任意源加入后屏蔽另一个源', '这个网段上的查询者'), b=bars([['IGMPv2 报告 0x16', 11, '11'], ['IGMPv2 离开 0x17', 5, '5'], ['IGMPv3 报告 0x22', 0, '0']], 11, mark=[2], done=[0, 1]), kv=KV([['只要别的源', '没收到:内核按源过滤'], ['屏蔽本机地址这个源', '仍然收到(原因没查)'], ['线上', '全是 v2:16 个报文'], ['路由器', '不知道源过滤']], ['屏蔽本机地址这个源'])),
]
A = mkartw('w34', 34, '网络协议,IGMP,IGMPv3,源过滤,组播,真实验证,动画演示',
    '手工构造 IGMPv2 / v3 查询与报告并用 tcpdump 与 scapy 交叉解码(v2 报文 8 字节,v3 报告 8 字节头 + 每条记录 8 字节起);本机套接字能按源过滤(只要别的源就收不到),但 IP_BLOCK_SOURCE 对本机回送的包没生效;线上全是 v2,过滤只在内核里。',
    'IGMPv3 比 v2 多了什么?“只接收某个源的组播”是怎么表达的?本机的套接字源过滤是真的吗,路由器知道吗?这篇手工构造各种 v2 / v3 报文用 tcpdump 和 scapy 一起解码,再用真实套接字测源过滤。',
    [('8 字节 / 16 字节', 'IGMPv2 报告与 IGMPv3 报告(1 条记录,0 个源)的 IGMP 部分大小'), ('0 个 v3', '本机加入 / 屏蔽 / 离开的过程中发出的 IGMPv3 报告个数:线上全是 v2(16 个报文)'), ('只要别的源 → 没收到', 'IP_ADD_SOURCE_MEMBERSHIP 只要另一个源时,本机内核对来自本机地址的组播的过滤结果')],
    [('v2 与 v3 的区别', '<p>v2 的查询和报告都是 8 字节、针对单个组;v3 报告可以带多条记录,每条记录有类型和源地址列表;v3 查询能带源列表,长度 ≥ 12 字节。</p>'),
     ('怎么区分', '<p>看查询的 IGMP 部分长度:8 字节且响应时间为 0 是 v1,8 字节且不为 0 是 v2,≥ 12 字节是 v3。</p>'),
     ('记录类型', '<p>v3 报告用 MODE_IS_* 报告当前状态,用 CHANGE_TO_* 和 ALLOW / BLOCK 报告变化,没有专门的 Leave。这些映射没有在线上验证,因为本机只发 v2。</p>'),
     ('源过滤', '<p>本机内核真的会按源地址过滤(只要别的源就收不到);屏蔽自己这个源的实验没有生效,原因没查。因为线上是 v2,路由器并不知道本机的源过滤。</p>')],
    steps,
    [ENV_W + '。第一至三节是手工构造的报文(文档地址 192.0.2.0/24、198.51.100.0/24),不是抓到的;第四节是真实套接字与 en0 上的抓包,发送方源地址就是本机地址,没有第二台主机,所以只能验证“本机地址”和一个虚构地址两种源',
     '没有验证:IGMPv3 报文在真实网络上的发送(本机在这个网段按 v2 说话);v3 查询的响应延迟与重传(Robustness);IGMP snooping 交换机对源过滤的处理;IP_BLOCK_SOURCE 没有屏蔽本机回送包的原因;SSM(源特定组播,232.0.0.0/8)的行为'],
    'IGMPv2 与 IGMPv3')
